function harness(initial=fixture(),unreadable=false){
  const events={},mainEvents={},winEvents={},nodes={},intervals=[];
  function node(id){return nodes[id]||(nodes[id]={innerHTML:'',textContent:'',querySelector:node,querySelectorAll:()=>[],style:{},attrs:{},classList:{toggle(){}},setAttribute(k,v){this.attrs[k]=v;},removeAttribute(k){delete this.attrs[k];},addEventListener(name,fn){if(id==='#main')mainEvents[name]=fn;},focus(){},insertAdjacentHTML(where,value){this.innerHTML=value+this.innerHTML;}});}
  const doc={querySelector:node,querySelectorAll:()=>[],addEventListener:(k,f)=>events[k]=f};
  let saved=unreadable?'{broken':JSON.stringify(initial),failure=false;
  const local={getItem:()=>saved,setItem:(k,v)=>{if(failure)throw Error('Quota exceeded');saved=v;}};
  const location={hash:'#dashboard'};
  const win={addEventListener:(k,f)=>winEvents[k]=f,scrollTo(){}};
  class Forms{constructor(f){this.fields=f.fields;}get(k){return this.fields[k]??null;}has(k){return Object.hasOwn(this.fields,k);}}
  const context=vm.createContext({window:win,document:doc,location,localStorage:local,console,Date,Math,JSON,Set,Map,String,Number,Error,URL,URLSearchParams,Intl,FormData:Forms,confirm:()=>true,setTimeout:()=>1,clearTimeout(){},setInterval:fn=>{intervals.push(fn);return 1;},Blob});
  vm.runInContext(fs.readFileSync(path.join(appDir,'model.js'),'utf8'),context);
  vm.runInContext(fs.readFileSync(path.join(appDir,'hierarchy.js'),'utf8'),context);
  vm.runInContext(fs.readFileSync(path.join(appDir,'tests.js'),'utf8'),context);
  vm.runInContext(fs.readFileSync(path.join(appDir,'app.js'),'utf8'),context);
  const fireHash=hash=>{location.hash=hash;winEvents.hashchange();};
  const click=dataset=>events.click({target:{closest:()=>({dataset})}});
  const submit=(id,fields,recordId='',subject='',extra={})=>mainEvents.submit({preventDefault(){},target:{id,fields,dataset:{...extra,id:recordId,subject},querySelector:()=>node('#form-error')}});
  return {node,fireHash,click,submit,mainEvents,tick:()=>intervals.forEach(fn=>fn()),get:()=>JSON.parse(saved),raw:()=>saved,setFailure:x=>failure=x};
}
